/**
 * Website typefaces embedded for server-side PDF generation.
 *
 * Clash Display (400/700) and JetBrains Mono (400/500) are the same
 * families loaded by the website through next/font. The WOFF2 sources are
 * converted to static, Latin-subset TTF instances so PDFKit can embed them
 * without reading files at runtime on Vercel.
 */

const CLASH_DISPLAY_REGULAR_BASE64 =
  '';

const CLASH_DISPLAY_BOLD_BASE64 =
  '';

const JETBRAINS_MONO_REGULAR_BASE64 =
  '';

const JETBRAINS_MONO_MEDIUM_BASE64 =
  '';

export const PDF_FONTS = {
  sans: 'FregoroClash',
  sansBold: 'FregoroClashBold',
  mono: 'FregoroMono',
  monoBold: 'FregoroMonoMedium',
} as const;

/** Register the website typefaces on a PDFKit document. */
export function registerPdfFonts(doc: PDFKit.PDFDocument): void {
  doc.registerFont(PDF_FONTS.sans, Buffer.from(CLASH_DISPLAY_REGULAR_BASE64, 'base64'));
  doc.registerFont(PDF_FONTS.sansBold, Buffer.from(CLASH_DISPLAY_BOLD_BASE64, 'base64'));
  doc.registerFont(PDF_FONTS.mono, Buffer.from(JETBRAINS_MONO_REGULAR_BASE64, 'base64'));
  doc.registerFont(PDF_FONTS.monoBold, Buffer.from(JETBRAINS_MONO_MEDIUM_BASE64, 'base64'));
}
